102	+fn exact_count(operation: &str, expected: usize, actual: usize) -> Result<()> {
103	+    if actual != expected {
104	+        return Err(Error::UnexpectedVcpuExit(format!(
105	+            "CPUID interception {operation}: transferred {actual} of {expected} MSRs"
106	+        )));
107	+    }
108	+    Ok(())
109	+}
