111	+fn read_state(vcpu: &VcpuFd) -> Result<MsrState> {
112	+    let mut values =
113	+        Msrs::from_entries(&[entry(PLATFORM_INFO, 0), entry(MISC_FEATURES_ENABLES, 0)])
114	+            .expect("fixed CPUID MSR read fits");
115	+    exact_count("read", 2, vcpu.get_msrs(&mut values)?)?;
116	+    Ok(MsrState {
117	+        platform: values.as_slice()[0].data,
118	+        features: values.as_slice()[1].data,
119	+    })
120	+}
