8	//! CPL3 CPUID fault admission and instruction retirement. The existing Tool
9	//! callback owns the result and any logical-time charge; this module adds none.
10	
11	use kvm_bindings::Msrs;
12	use kvm_bindings::kvm_msr_entry;
13	use kvm_bindings::kvm_regs;
14	use kvm_ioctls::Kvm;
15	use kvm_ioctls::VcpuFd;
16	use reverie::CpuIdResult;
17	
18	use crate::Error;
19	use crate::Result;
20	
21	const PLATFORM_INFO: u32 = 0xce;
22	const MISC_FEATURES_ENABLES: u32 = 0x140;
23	const SUPPORT: u64 = 1 << 31;
24	const ENABLE: u64 = 1;
25	
26	#[derive(Clone, Copy)]
27	struct MsrState {
28	    platform: u64,
29	    features: u64,
30	}
31	
32	/// State belongs to one real vCPU, never to a process snapshot or a Tool type.
33	/// Retain the original before the first write, including after a failed rollback.
34	#[derive(Default)]
35	pub(crate) struct Interception {
36	    original: Option<MsrState>,
37	    enabled: bool,
38	}
39	
40	fn entry(index: u32, data: u64) -> kvm_msr_entry {
41	    kvm_msr_entry {
42	        index,
43	        data,
44	        ..Default::default()
45	    }
46	}
47	
48	fn exact_count(operation: &str, expected: usize, actual: usize) -> Result<()> {
49	    if actual != expected {
50	        return Err(Error::UnexpectedVcpuExit(format!(
51	            "CPUID interception {operation}: transferred {actual} of {expected} MSRs"
52	        )));
53	    }
54	    Ok(())
55	}
56	
57	fn read_state(vcpu: &VcpuFd) -> Result<MsrState> {
58	    let mut values =
59	        Msrs::from_entries(&[entry(PLATFORM_INFO, 0), entry(MISC_FEATURES_ENABLES, 0)])
60	            .expect("fixed CPUID MSR read fits");
61	    exact_count("read", 2, vcpu.get_msrs(&mut values)?)?;
62	    Ok(MsrState {
63	        platform: values.as_slice()[0].data,
64	        features: values.as_slice()[1].data,
65	    })
66	}
67	
68	fn write_one(vcpu: &VcpuFd, index: u32, value: u64) -> Result<()> {
69	    let values = Msrs::from_entries(&[entry(index, value)]).expect("one CPUID MSR write fits");
70	    exact_count(&format!("write {index:#x}"), 1, vcpu.set_msrs(&values)?)
71	}
72	
73	impl Interception {
74	    pub(crate) fn enabled(&self) -> bool {
75	        self.enabled
76	    }
77	
78	    pub(crate) fn configure(&mut self, vcpu: &VcpuFd, enabled: bool) -> Result<()> {
79	        if !enabled {
80	            // A fresh tool-less backend never requests this optional feature.
81	            return self.restore(vcpu);
82	        }
83	        if self.enabled {
84	            return self.verify(vcpu);
85	        }
86	        if self.original.is_some() {
87	            return Err(Error::UnexpectedVcpuExit(
88	                "CPUID interception has unresolved MSR restoration".to_owned(),
89	            ));
90	        }
91	        let kvm = Kvm::new()?;
92	        if !kvm
93	            .get_msr_feature_index_list()?
94	            .as_slice()
95	            .contains(&PLATFORM_INFO)
96	        {
97	            return Err(Error::UnexpectedVcpuExit(
98	                "CPUID interception unsupported: PLATFORM_INFO feature MSR absent".to_owned(),
99	            ));
100	        }
101	        let mut feature =
102	            Msrs::from_entries(&[entry(PLATFORM_INFO, 0)]).expect("one feature MSR fits");
103	        exact_count("feature read", 1, kvm.get_msrs(&mut feature)?)?;
104	        if feature.as_slice()[0].data & SUPPORT == 0 {
105	            return Err(Error::UnexpectedVcpuExit(
106	                "CPUID interception unsupported: fault support bit absent".to_owned(),
107	            ));
108	        }
109	        let original = read_state(vcpu)?;
110	        if original.features & ENABLE != 0 {
111	            return Err(Error::UnexpectedVcpuExit(
112	                "CPUID interception was armed without an owning Tool consumer".to_owned(),
113	            ));
114	        }
115	        self.original = Some(original);
