    code.extend_from_slice(&timestamp_assertion_program());
    let failure = code.len();
    code.extend_from_slice(&[
        0xb8, 0xe7, 0, 0, 0, 0xbf, 22, 0, 0, 0, 0x0f, 0x05, 0x0f, 0x0b,
