            let Error::SharedFailure(cause) = error else {
                panic!("expected exactly the real shared exit-hook failure");
            };
            assert!(
                matches!(cause.as_ref(), Error::Reverie(reverie::Error::Errno(e)) if *e == Errno::EIO)
