        memory: GuestMemory,
        cpuid_policy: CpuidPolicy,
        stdin: Option<File>,
    ) -> Result<Self> {
        install_worker_interrupt_handler()?;
        const INITIALIZATION_ATTEMPTS: usize = 3;
        let mut attempts = 0;
        let InitializedKvmResources {
            vcpu,
