        let memory = self.memory.snapshot()?;
        hide_tool_scratch_pages(&memory)?;
        Ok(KvmProcessSnapshot {
            memory,
            registers: self.vcpu.get_regs()?,
            xsave: self.vcpu.get_xsave()?,
