    if kind not in ('metadata','compile'):
        inputs += [file_record(HERE/'retained-binaries/BINDING.json'),file_record(HERE/'controls/compile/artifacts.json')]
    if kind in ('check','format'):
        qualified=json_read(HERE/'controls/compile/result.json');require(qualified['accepted']and qualified['terminal_authenticated'],'successor compile did not qualify')
        inputs += [file_record(HERE/'controls/compile/result.json'),file_record(HERE/'retained-binaries/ARTIFACTS.json')]
        for artifact_id,record in json_read(HERE/'retained-binaries/ARTIFACTS.json').items():
            artifact=record['file'];check_file(artifact,executable=True);inputs.append(artifact)
            extra,symlinks=loader('test-'+artifact_id,artifact,env);inputs+=extra;links+=symlinks
    if name=='core-check':
        argv=[cargo,'check','--offline','--locked','-p','reverie-core','-p','reverie-ptrace','--message-format=json']
    elif kind=='check':
