1	use super::*;
2	
3	#[derive(Default)]
4	struct LowerTool;
5	#[reverie::tool]
6	impl Tool for LowerTool {
7	    type GlobalState = ();
8	    type ThreadState = ();
9	}
10	#[derive(Default)]
11	struct AdapterTool(LowerTool);
12	impl AsMut<LowerTool> for AdapterTool {
13	    fn as_mut(&mut self) -> &mut LowerTool {
14	        &mut self.0
15	    }
16	}
17	#[reverie::tool]
18	impl Tool for AdapterTool {
19	    type GlobalState = ();
20	    type ThreadState = Box<()>;
21	}
22	struct RefusingExecutor;
23	impl GuestSyscallExecutor<AdapterTool> for RefusingExecutor {
24	    fn read_clock(&self) -> Result<u64> {
25	        Err(Error::GuestClock(
26	            "signal test adapter has no guest counter".into(),
27	        ))
28	    }
29	
30	    fn execute(&mut self, _: &SyscallRequest, _: &GuestMemory) -> i64 {
31	        panic!("terminal cancellation executed a syscall")
32	    }
33	    fn tail_injection_allowed(&self, _request: &SyscallRequest) -> bool {
34	        false
35	    }
36	    fn complete_injection<'a>(
37	        &'a mut self,
38	        _: ToolContext<'a, AdapterTool>,
39	    ) -> Pin<Box<dyn Future<Output = Result<InjectionCompletion>> + Send + 'a>>
40	    where
41	        AdapterTool: 'a,
42	    {
43	        panic!("terminal cancellation completed an injection")
44	    }
45	}
46	
47	#[test]
48	fn terminal_cancellation_and_into_guest_forwarding_do_not_inject_or_start_children() {
49	    for adapted in [false, true] {
50	        for thread in [false, true] {
51	            let memory = GuestMemory::new(0, STACK_CAPACITY).unwrap();
52	            let mut state = Box::new(());
53	            let mut executor = RefusingExecutor;
54	            let subscriptions = Subscription::none();
55	            let signal = Arc::new(Mutex::new(None));
56	            let starts = Arc::new(Mutex::new(Vec::new()));
57	            let (sender, receiver) = std::sync::mpsc::channel();
58	            let gate = ChildStartGate::new(sender);
59	            starts.lock().unwrap().push(if thread {
60	                PendingChildStart::tool_thread(2, gate)
61	            } else {
62	                PendingChildStart::fork_process(2, gate)
63	            });
64	            let mut guest = KvmGuest::<AdapterTool>::new(
65	                Pid::from_raw(1),
66	                Pid::from_raw(2),
67	                Arc::new(AdapterTool::default()),
68	                memory,
69	                &[],
70	                // SAFETY: this test never reads the register fields.
71	                unsafe { std::mem::zeroed() },
72	                &mut state,
73	                &mut executor,
74	                &(),
75	                None,
76	                &(),
77	                &subscriptions,
78	                signal.clone(),
79	                starts.clone(),
80	                crate::bootstrap::TOOL_STACK_TOP,
81	                Arc::new(AtomicBool::new(false)),
82	            );
83	            let outcome = futures::executor::block_on(drive_handler(
84	                async {
85	                    if adapted {
86	                        <_ as Guest<LowerTool>>::cancel_current_thread(&mut guest.into_guest())
87	                            .await
88	                    } else {
89	                        guest.cancel_current_thread().await
90	                    }
91	                },
92	                signal,
93	                starts.clone(),
94	                std::future::pending(),
95	            ));
96	            assert!(
97	                matches!(outcome, HandlerOutcome::ThreadCancelled),
98	                "adapted={adapted}"
99	            );
100	            assert_eq!(
101	                receiver.try_recv(),
102	                Err(std::sync::mpsc::TryRecvError::Empty)
103	            );
104	            assert_eq!(starts.lock().unwrap().len(), 1);
105	            // The owning caller, after dropping the callback, releases successful starts.
106	            start_pending_children(&starts).unwrap();
107	            assert_eq!(receiver.recv().unwrap(), ChildStartCommand::Start);
108	            assert!(starts.lock().unwrap().is_empty());
109	        }
110	    }
111	}
112	
113	#[test]
114	fn terminal_exit_retires_only_current_identity_and_preserves_existing_status() {
115	    let cwd = std::env::current_dir().unwrap();
116	    let memory = GuestMemory::new(0, 4096).unwrap();
117	    for established in [
118	        None,
119	        Some((libc::SYS_exit, 17, false)),
120	        Some((libc::SYS_exit_group, 37, true)),
121	    ] {
122	        let mut leader = ElfExecutor::new(crate::executor::test_loaded_state_for_vm(&cwd), false);
123	        let mut retired = leader.thread_child(7).unwrap();
124	        let _peer = leader.thread_child(8).unwrap();
125	        let probe = |tid| SyscallRequest::new(libc::SYS_tgkill as u64, [1, tid, 0, 0, 0, 0]);
126	        assert_eq!(leader.execute(&probe(7), &memory), 0);
127	        if let Some((number, status, _)) = established {
128	            assert_eq!(
129	                retired.execute(
130	                    &SyscallRequest::new(number as u64, [status, 0, 0, 0, 0, 0]),
131	                    &memory
132	                ),
133	                0
134	            );
135	        }
136	        let exit = retired.cancel_current_thread();
137	        assert_eq!(
138	            exit.status,
139	            established.map_or(ExitStatus::SUCCESS, |(_, status, _)| ExitStatus::Exited(
140	                status as i32
141	            ))
142	        );
143	        assert_eq!(exit.group, established.is_some_and(|(_, _, group)| group));
144	        assert!(
145	            retired.take_exit().is_none(),
146	            "terminal state is consumed once"
147	        );
148	        assert_eq!(leader.execute(&probe(7), &memory), -i64::from(libc::ESRCH));
149	        assert_eq!(
150	            leader.execute(&probe(8), &memory),
151	            0,
152	            "a live peer stays registered"
153	        );
154	        let _replacement = leader.thread_child(7).unwrap();
155	        drop(retired);
